// Master data: 20 crops, all 36 Maharashtra districts and one main mandi per
// district. Generated by tools/build_catalogue.py (the backend loads the same
// JSON), so edit the tool and re-run it rather than changing values here.

import type { Crop, District, Mandi } from '../types';
import data from './catalogue.data.json';

export const CROPS = data.crops as Crop[];
export const DISTRICTS = data.districts as District[];
export const MANDIS = data.mandis as Mandi[];

export const getCrop = (id: string) => CROPS.find((c) => c.id === id);
export const getDistrict = (id: string) => DISTRICTS.find((d) => d.id === id);
export const getMandi = (id: string) => MANDIS.find((m) => m.id === id);

/** The offline demo (mock mode) only has hand-written market signals for the original five pilot crops. */
export const DEMO_CROP_IDS = ['maize', 'soybean', 'onion', 'tur', 'tomato'];
export const DEMO_CROPS = CROPS.filter((c) => DEMO_CROP_IDS.includes(c.id));
